css:
@page { size: A4; margin: 0; }
body { margin: 0; padding: 0; -webkit-print-color-adjust: exact; }

.page {
    position: relative;
    width: 210mm;
    height: 297mm;
    background-color: #fff;
    font-family: 'Arial', sans-serif;
    overflow: hidden;
}

.logo-text h1 { margin-top: 30px; font-size: 32px; letter-spacing: 0px; line-height: 0.2; }
.logo-text p { margin-bottom: 10px; font-size: 10px; letter-spacing: 0px; }

/* Professional Header (No Logo) */
.header-top {
    background-color: #006363;
    height: 80px;
    padding: 0 40px;
    display: flex;
    align-items: center;
}

.header-bar {
    background-color: #00ced1;
    height: 22px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0 25px;
    color:#fff;
    font-size: 9px;
    font-weight: bold;
}

/* Content Area */
.content {
    position: relative;
    z-index: 10;
    padding: 30px 22mm;
    font-family: "Times New Roman", serif;
    text-align: justify;
}

.content h2 { text-align: center; margin-bottom: 25px; font-size: 22px; font-weight: bold; }
.content p { font-size: 16px; line-height: 1.55; margin-bottom: 14px; text-indent: 40px; color: #000 !important; }

.details p { text-indent: 0; margin-bottom: 5px; font-size: 16px; }

.signature { margin-top: 36px; font-weight: bold; font-size: 16px; text-indent: 0; }

/* Footer Styling */
.footer-area {
    position: absolute;
    bottom: 0;
    width: 100%;
    text-align: center;
}

.head-office { color: #007979; font-weight: bold; margin: 0; font-size: 12px; }
.address, .contact { color: #007979; margin: 2px 0; font-size: 10px; }
.footer-graphic { display: flex; height: 15px; width: 100%; margin-top: 10px; }
.bar-teal { 
    background-color: #006363; flex: 4; 
    clip-path: polygon(0 0, 96% 0, 100% 100%, 0% 100%); 
}
.bar-cyan { 
    background-color: #00ced1; flex: 1; 
    margin-left: -3%; 
    clip-path: polygon(30% 0, 100% 0, 100% 100%, 0% 100%); 
}
